parameters.jsonBody:
={
  "contents": [{
    "parts": [{
      "text": "Classify the candidate skills into EXACTLY ONE of these 5 categories:
- automation-heavy
- web dev
- data
- voice/calling
- other

Examples:
- 'React, TypeScript, CSS, Node, Fullstack, Frontend, Backend, Django, AWS' -> web dev
- 'Python, SQL, Tableau, Pandas, Analytics, PowerBI, Excel' -> data
- 'Zapier, Make, n8n, RPA, Selenium, Automation, Bash' -> automation-heavy
- 'Telemarketing, Telesales, Cold calling, Customer support, BPO, Voice agent' -> voice/calling
- 'Unknown, generic, or non-technical unlisted skills' -> other

Candidate Skills: {{$json.skills_text}}

Rules: Output ONLY one of the exact 5 category strings above in lowercase. No quotes, no markdown, no explanation."
    }]
  }]
}

parameters.jsCode:
const originalPerson = $('Fetch Untagged People').item.json;
const personId = originalPerson.person_id || originalPerson.id;
const rawSkills = String(originalPerson.skills_text || originalPerson.skills || '').toLowerCase();

const geminiPart = $input.item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const cleanGemini = String(geminiPart).toLowerCase().replace(/[^a-z0-9\-\/ ]/g, ' ').replace(/\s+/g, ' ').trim();

const allowedCategories = ['automation-heavy', 'web dev', 'data', 'voice/calling', 'other'];
let finalCategory = 'other';

// 1. Direct match with valid 5 categories
for (const cat of allowedCategories) {
  if (cleanGemini === cat || cleanGemini.includes(cat)) {
    finalCategory = cat;
    break;
  }
}

// 2. Fallback keyword mapping to strictly one of the 5 allowed categories
if (finalCategory === 'other') {
  if (/n8n|zapier|make|rpa|selenium|uipath|scripting|automation|playwright/i.test(cleanGemini) || /n8n|zapier|make|rpa|selenium|uipath|scripting|automation|playwright/i.test(rawSkills)) {
    finalCategory = 'automation-heavy';
  } else if (/react|node|html|css|django|flask|vue|angular|frontend|backend|fullstack|javascript|typescript|express|laravel|php|ruby|cloud|devops|aws|docker|kubernetes|flutter|mobile/i.test(cleanGemini) || /react|node|html|css|django|flask|vue|angular|frontend|backend|fullstack|javascript|typescript|express|laravel|php|ruby|cloud|devops|aws|docker|kubernetes|flutter|mobile/i.test(rawSkills)) {
    finalCategory = 'web dev';
  } else if (/sql|pandas|analytics|tableau|powerbi|bi|etl|machine learning|data science|postgresql|mysql|data|excel/i.test(cleanGemini) || /sql|pandas|analytics|tableau|powerbi|bi|etl|machine learning|data science|postgresql|mysql|data|excel/i.test(rawSkills)) {
    finalCategory = 'data';
  } else if (/telemarketing|telesales|cold call|calling|voice|bpo|customer support|support/i.test(cleanGemini) || /telemarketing|telesales|cold call|calling|voice|bpo|customer support|support/i.test(rawSkills)) {
    finalCategory = 'voice/calling';
  }
}

// Extra sanity check
if (!allowedCategories.includes(finalCategory)) {
  finalCategory = 'other';
}

return {
  json: {
    person_id: personId,
    category: finalCategory
  }
};
